import XCTest
@testable import CheatDays

/// Generated by design/chains/_tools/match-test.js --swift: the app's chain matcher gives what the test tool's copy
/// gives on the real menus (a sure match, or nothing, never another item).
final class ChainMenuTests: XCTestCase {
    private let chains: [(String, String, String?)] = [
        ("AU", "GYG", "Guzman y Gomez"),
        ("AU", "Hungry Jacks", "Hungry Jack's"),
        ("GB", "Pret", "Pret A Manger"),
        ("AU", "Greggs", nil),
        ("GB", "Zambrero", nil),
        ("AU", "Maccas", nil),
        ("AU", "Joe's Cafe", nil),
    ]
    private let items: [(String, String, String, String?)] = [
        ("AU", "Hungry Jack's", "Whopper", "Whopper"),
        ("AU", "Hungry Jacks", "Whopper Cheese", "Whopper Cheese"),
        ("AU", "HJ's", "Chicken Royale", "Chicken Royale"),
        ("AU", "Hungry Jack's", "Hungry Jack's Stacker Quad", "Stacker Quad"),
        ("AU", "Hungry Jack's", "Large vanilla shake", "Shake Vanilla Large"),
        ("AU", "Hungry Jack's", "Small vanilla shake", "Shake Vanilla Small"),
        ("AU", "Hungry Jack's", "Chocolate sundae large", "Sundae Chocolate Large"),
        ("AU", "Hungry Jack's", "Nugget 3 pack", "Nugget 3 Pack"),
        ("AU", "Hungry Jack's", "Big Mac", nil),
        ("AU", "Hungry Jack's", "Zinger burger", nil),
        ("AU", "Hungry Jack's", "Pad thai", nil),
        ("AU", "Zambrero", "Classic burrito barbacoa beef", "Classic Burrito - Barbacoa Beef"),
        ("AU", "Zambrero", "Cali burrito pork", "Cali Burrito - Pork"),
        ("AU", "Zambrero", "Whopper", nil),
        ("AU", "GYG", "Cali Burrito Mild BBQ Beef Rib", "Cali Burrito - Mild BBQ Beef Rib"),
        ("AU", "Guzman y Gomez", "Big Mac", nil),
        ("AU", "Subway", "Pizza Melt 6 inch", "Pizza Melt (6-inch sub)"),
        ("AU", "Subway", "Sausage roll", nil),
        ("GB", "Greggs", "Sausage roll", "Sausage Roll"),
        ("GB", "Greggs", "Steak bake", "Steak Bake"),
        ("GB", "Greggs", "Large americano", "Large Americano"),
        ("GB", "Greggs", "Regular hot chocolate", "Regular Hot Chocolate"),
        ("GB", "Greggs", "Tuna crunch baguette", "Tuna Crunch Baguette"),
        ("GB", "Greggs", "Big Mac", nil),
        ("GB", "Greggs", "Chicken burrito", nil),
        ("GB", "KFC", "Fillet burger", "Fillet Burger"),
        ("GB", "KFC", "Pepsi Max large", "Pepsi Max Large"),
        ("GB", "KFC", "Whopper", nil),
        ("GB", "Pret", "Flat white", "Flat White"),
        ("GB", "Pret", "Chai latte", "Chai Latte"),
        ("GB", "Pret A Manger", "Pret sausage roll", "Pret's Sausage Roll"),
        ("GB", "Pret", "Big Mac", nil),
        ("GB", "Starbucks", "Grande caramel frappuccino whole milk", "Caramel Frappuccino® - whole milk Grande"),
        ("GB", "Greggs", "Vegan sausage roll", nil),
        ("GB", "Greggs", "Vegan roll", "Vegan Roll Pork-Free"),
        ("AU", "Hungry Jacks", "Double whopper", "Whopper Double"),
        ("AU", "Hungry Jacks", "Large chips", "Chips Large"),
        ("AU", "Hungry Jacks", "Chips", "Chips Medium"),
        ("AU", "Hungry Jacks", "Coke no sugar large", "Coke Zero POM Large"),
        ("AU", "Hungry Jacks", "Chicken burger", nil),
        ("GB", "KFC", "Zinger burger", "Zinger Burger"),
        ("GB", "KFC", "Large fries", "Large Signature Fries"),
        ("GB", "KFC", "Popcorn chicken", nil),
        ("AU", "Zambrero", "Chicken burrito", nil),
        ("GB", "Pret", "Tuna baguette", nil),
    ]

    func testChainsAreKnownOnlyWhereTheyAre() {
        for (code, shop, want) in chains { XCTAssertEqual(ChainMenu.chain(shop, code: code)?.name, want, "(code) (shop)") }
    }

    func testItemsMatchSurelyOrNotAtAll() {
        for (code, shop, asked, want) in items {
            guard let c = ChainMenu.chain(shop, code: code) else { XCTFail("no chain (shop) in (code)"); continue }
            XCTAssertEqual(ChainMenu.item(asked, in: c)?.name, want, "(shop): (asked)")
        }
    }

    /// A whole order: every item from the chain's own rows, and a total far from the AI's left alone.
    func testAnOrderTakesTheChainsNumbers() {
        let e: JSON = ["shop": "Hungry Jack's", "shop_items": "Whopper x1; Chips Large x1", "kcal_total": 900, "parts": [Any]()]
        let out = ChainMenu.order(e, code: "AU")
        XCTAssertNotNil(out)
        XCTAssertEqual(list(out?["parts"]).count, 2)
        XCTAssertEqual(str(out?["chain"]), "Hungry Jack's")
        var far = e; far["kcal_total"] = 5000
        XCTAssertNil(ChainMenu.order(far, code: "AU"), "a total under half the AI's is taken as a wrong match")
        var unsure = e; unsure["shop_items"] = "Whopper x1; Chicken burger x1"
        XCTAssertNil(ChainMenu.order(unsure, code: "AU"), "one item not surely matched: nothing changes")
        XCTAssertNil(ChainMenu.order(e, code: "GB"), "Hungry Jack's isn't a UK chain")
    }
}
